head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.file_flag = "N";
scwin.listComiteDelibCaseSeq = '';
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyListComiteDelibCaseSeq = "";
scwin.contnId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        panel_Term.hide();
        const parentWin = $c.frame.path("../");
        scwin.strKeyListComiteDelibCaseSeq = parentWin.clickListComiteDelibCaseSeq;
        await scwin.listReqInf();
        await scwin.listCmt();
        if (scwin.strKeyListComiteDelibCaseSeq === "") {
            let dNow = new Date();
            tbx_LIST_COMITE_RND_EXEC_YY.setValue(dNow.getYear());
        } else {
            tbx_LIST_COMITE_RND_EXEC_YY.setReadOnly(true);
            tbx_LIST_COMITE_RND.setReadOnly(true);
        }
        const parentFrameID = $c.stf.getQuery(frame.srcUrl, "frameID");
        if (parentFrameID.indexOf('STF60000') !== -1) {
            img_Save.hide();
            img_Delete.hide();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Cmt_OnLoadCompleted
 * @description dts_Cmt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Cmt_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_Cmt.getRowCount() > 0) {
            scwin.setKeyCtrOnUpd(); // 조회직후에는 수정상태

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60004.dts_Cmt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ReqInf_OnLoadCompleted
 * @description dts_ReqInf 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ReqInf_OnLoadCompleted = async function(rowcount) {
    try {
        await scwin.read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.dts_ReqInf_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name tr_Save_OnFail
 * @description tr Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnFail = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_FAIL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.tr_Save_OnFail" });
    }
};

/**
 * @method
 * @name tr_Save_OnSuccess
 * @description tr Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnSuccess = async function() {
    try {
        scwin.indexingElasitcSearch();
        await $c.win.alert(scwin.MSG_TR_DOME);
        if (dts_Cmt.getRowCount() > 0) {
            scwin.setKeyCtrOnUpd(); // 조회직후에는 수정상태

        }
        await scwin.listReqInf();
        await scwin.listCmt();
        scwin.parentRefresh();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.tr_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_SetComiteDd_onclick
 * @description img_SetComiteDd 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_SetComiteDd_onclick = async function() {
    try {
        if (scwin.strKeyListComiteDelibCaseSeq !== "") {
            await $c.win.alert('위원회일은 수정할 수 없습니다');
            return;
        } else {
            scwin.showCalendar(med_ListComiteDd);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.img_SetComiteDd_onclick" });
    }
};

/**
 * @method
