        await scwin.save("I");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.img_Save_onclick" });
    }
};

/**
 * @method
 * @name img_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Delete_onclick = async function() {
    try {
        await scwin.deleteAll();
    } catch (ex) {
