    }
};

/**
 * @method
 * @name btn_lineadd1_onclick
 * @description 「파일첨부」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd1_onclick = async function() {
    try {
        if (dts_ReqInf.getRowCount() === 0) {
            await $c.win.alert('안건을 등록해 주십시오');
            return;
        }
        if (dts_fileList.getCellData(1, "filename") === "") {
            dts_fileList.insertRow();
            inf_find.open();
            if (inf_find.getValue() !== "") {
                dts_fileList.setCellData(1, "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
                txb_seq.setValue("1");
                txb_file_name1.setValue(inf_find.getValue());
            } else {
                dts_fileList.removeRow(1);
                txb_file_name1.setValue("");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.btn_lineadd1_onclick" });
    }
};

/**
 * @method
 * @name btn_lineadd2_onclick
 * @description 「파일첨부」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd2_onclick = async function() {
    try {
        if (dts_ReqInf.getRowCount() === 0) {
            await $c.win.alert('안건을 등록해 주십시오');
            return;
        }
        if (dts_fileList.getCellData(2, "filename") === "") {
            dts_fileList.insertRow();
            inf_find.open();
            if (inf_find.getValue() !== "") {
                dts_fileList.setCellData(2, "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
                txb_seq.setValue("2");
                txb_file_name2.setValue(inf_find.getValue());
            } else {
                dts_fileList.removeRow(2);
                txb_file_name2.setValue("");
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.btn_lineadd2_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete1_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete1_onclick = function() {
    try {
        dts_fileList.setBroadcast(false);
        for (let j = 1; j < dts_fileList.getRowCount() + 1; j++) {
            if (dts_fileList.getCellData(j, "SEQ") === 1) {
                dts_fileList.removeRow(j);
                txb_file_name1.setValue("");
                scwin.file_flag = "Y";
                break;
            }
        }
        dts_fileList.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60004.btn_linedelete1_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete2_onclick
 * @description 「파일삭제」 클릭 이벤트
