/**
 * @method
 * @name dts_fileList_OnLoadCompleted
 * @description dts_fileList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_fileList_OnLoadCompleted = function(rowcount) {
    try {
        const setArr = [txb_file_name1, txb_file_name2];
        if (rowcount > 0) {
            let k;
            // rowcount는 5인데 첨부파일은 2임, undefined 오류 발생하여 setArr.length로 변경
            // for(var i=0 ; i < rowcount ; i++ ){
            for (let i = 0; i < setArr.length; i++) {
                k = dts_fileList.getCellData(i + 1, "SEQ");
                setArr[k - 1].setValue(dts_fileList.getCellData(i + 1, "filename"));
                // if(dts_fileList.NameString(i+1, "filename") ==""){setBtn[i].disabled=true;}

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60004.dts_fileList_OnLoadCompleted" });
    }
};

