/**
 * @method
 * @name btn_append_onclick
 * @description 「행추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_append_onclick = async function() {
    try {
        await scwin.addNewCmt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.btn_append_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_delete_onclick = function() {
    try {
        let count = dts_Cmt.getRowCount();
        dts_Cmt.setBroadcast(false);
        for (let j = 1; j <= count + 1; j++) {
            if (dts_Cmt.getCellData(j, "CHECK") === 'T') {
                dts_Cmt.removeRow(j);
                scwin.deleteRow();
            }
        }
        dts_Cmt.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60004.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name grd_cmt_onheadcheckclick
 * @description grd_cmt onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_cmt_onheadcheckclick = function(col, colid, bCheck) {
    try {
        let count = dts_Cmt.getRowCount();
        if (bCheck === '1') {
            dts_Cmt.setBroadcast(false);
            for (let j = 1; j <= count + 1; j++) {
                dts_Cmt.setCellData(j, "CHECK", 'T');
            }
            dts_Cmt.setBroadcast(true, true);
        } else {
            dts_Cmt.setBroadcast(false);
            for (let j = 1; j <= count + 1; j++) {
                dts_Cmt.setCellData(j, "CHECK", '');
            }
            dts_Cmt.setBroadcast(true, true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF60004.grd_cmt_onheadcheckclick" });
    }
};

/**
 * @method
 * @name tr_Delete_OnSuccess
 * @description tr Delete On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Delete_OnSuccess = async function() {
    try {
        scwin.indexingElasitcSearch();
        await $c.win.alert(scwin.MSG_TR_DOME);
        scwin.strKeyListComiteDelibCaseSeq = '';
        await scwin.listReqInf();
        await scwin.listCmt();
        scwin.parentRefresh();
        let dNow = new Date();
        tbx_LIST_COMITE_RND_EXEC_YY.setValue(dNow.getYear());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF60004.tr_Delete_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description search function end
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(jobType) {
    // 2009.05.12 위원회일/철회일 필수 체크
    if (med_ListComiteDd.getValue() === "") {
        await $c.win.alert("위원회일을 입력하여 주세요");
        med_ListComiteDd.focus();
        return false;
    }
    const check = scwin.fileYnCheck();
    let vScrenProcTpCd;
    if (jobType === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    const cnt = dts_Cmt.getRowCount();
    for (let i = 1; i < cnt + 1; i++) {
        const comiteCaseNm = dts_Cmt.getCellData(i, "COMITE_CASE_NM");
        const comiteCaseNo = dts_Cmt.getCellData(i, "COMITE_CASE_NO");
        // var comiteCaseDtlNo = dts_Cmt.NameString(i, "COMITE_CASE_DTL_NO");
        dts_Cmt.setCellData(i, "COMITE_CASE_DTL_NO", '1');
        const comiteCaseTpCd = dts_Cmt.getCellData(i, "COMITE_CASE_TP_CD");
        if (comiteCaseNo === '') {
            await $c.win.alert('[안건번호]가 입력되지 않았습니다.');
            return false;
        }
        if (comiteCaseTpCd === '') {
            await $c.win.alert('[안건구분]이 입력되지 않았습니다.');
            return false;
        }
        if (comiteCaseNm === '') {
            await $c.win.alert('[안건명]이 입력되지 않았습니다.');
            return false;
        }
    }
    for (let i = 1; i < cnt + 1; i++) {
        const caseNo = dts_Cmt.getCellData(i, "COMITE_CASE_NO");
        let dup = 0;
        for (let j = 1; j < cnt + 1; j++) {
            const caseNo1 = dts_Cmt.getCellData(j, "COMITE_CASE_NO");
            if (caseNo === caseNo1) {
                if (dup === 1) {
                    await $c.win.alert('[안건번호]가 중복 건이 있습니다.');
                    return false;
                } else {
                    dup = 1;
                }
            }
        }
    }
    if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
        if (scwin.strKeyListComiteDelibCaseSeq === "") {
            scwin.listComiteDelibCaseSeq = await scwin.getListComiteDelibCaseSeq();
            dts_ReqInf.insertRow();
            dts_ReqInf.setCellData(1, "LIST_COMITE_DELIB_CASE_SEQ", scwin.listComiteDelibCaseSeq);
            scwin.strKeyListComiteDelibCaseSeq = scwin.listComiteDelibCaseSeq;
        }
        tr_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_tr_Save",
            action : "/ComiteDelib.do",
            ref : "dts_ReqInf,dts_Cmt,dts_fileList",
            target : "tr_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else if (!$c.cp.isModified(dts_Cmt) && !$c.cp.isModified(dts_ReqInf) && check === "Y") {
        await scwin.fileInsert();
    } else {
        await $c.win.alert(scwin.MGS_NO_UPDT);
    }
};

/**
