/**
 * @method
 * @name listCmt
 * @description list Cmt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listCmt = async function() {
    const sbmOptions = {
        id : "sbm_dts_Cmt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Cmt=body.content",
        isProcessMsg : false
