/**
 * @method
 * @name deleteRow
 * @description delete Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.deleteRow = function() {
    let count = dts_Cmt.getRowCount();
    dts_Cmt.setBroadcast(false);
    for (let j = 1; j <= count + 1; j++) {
        if (dts_Cmt.getCellData(j, "CHECK") === 'T') {
            dts_Cmt.removeRow(j);
        }
    }
    dts_Cmt.setBroadcast(true, true);
};

